// t(name, keywords, notes, questions, quiz) makes one topic.
// In quiz: [question, [options], position of correct option (0 = first)].
// To add a new topic later, copy one t(...) line and change the text.

const t = (name, keywords, notes, questions, quiz) => ({
  name, keywords, notes, questions,
  quiz: quiz.map(([question, options, answer]) => ({ question, options, answer }))
});

